import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { supabaseService } from '../../services/supabaseService';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import ContactHero from './components/ContactHero';
import WhatsAppSection from './components/WhatsAppSection';
import ContactMethods from './components/ContactMethods';
import ContactForm from './components/ContactForm';
import FAQSection from './components/FAQSection';
import LocationMap from './components/LocationMap';
import HubComingSoon from './components/HubComingSoon';

const Contact = () => {
  const contactData = useSelector((state) => state.content.contact);
  const [liveUserCount, setLiveUserCount] = useState(0);
  const [settings, setSettings] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [count, siteSettings] = await Promise.all([
          supabaseService.getUserCount(),
          supabaseService.getSiteSettings()
        ]);
        setLiveUserCount(count);
        setSettings(siteSettings);
      } catch (error) {
        console.error("Error fetching contact data:", error);
      }
    };
    fetchData();
    window.scrollTo(0, 0);
  }, []);

  if (!contactData) return null;

  return (
    <div className="min-h-screen flex flex-col bg-[var(--color-background)]">
      <Header />

      <main className="flex-1">
        <ContactHero data={contactData.hero} />
        
        {settings?.is_hub_announced && <HubComingSoon />}

        <WhatsAppSection data={{
          ...contactData.whatsapp,
          memberCount: `${liveUserCount.toLocaleString()} Active Members`
        }} />
        <ContactMethods data={contactData.methods} />
        <div id="contact-form">
          <ContactForm />
        </div>
        <FAQSection data={contactData.faqs} />
        {!settings?.is_hub_announced && <LocationMap data={contactData.location} />}
      </main>

      <Footer />
    </div>
  );
};

export default Contact;