import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { supabaseService } from '../../../services/supabaseService';
import Input from '../../../components/ui/Input';
import Select from '../../../components/ui/Select';
import Button from '../../../components/ui/Button';
import { Checkbox } from '../../../components/ui/Checkbox';
import Icon from '../../../components/AppIcon';
import { useToast } from '../../../contexts/ToastContext';

const ContactForm = () => {
  const { addToast } = useToast();
  const location = useLocation();
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    inquiryType: '',
    subject: '',
    message: '',
    agreeToTerms: false,
    bot_trap: '' // Honeypot field
  });

  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const type = params.get('type');
    const subject = params.get('subject');
    
    if (type) {
      setFormData(prev => ({ ...prev, inquiryType: type }));
    }
    
    if (subject) {
      setFormData(prev => ({ 
        ...prev, 
        subject: subject,
        // Auto-select technical support for MFA issues
        inquiryType: subject.toLowerCase().includes('mfa') ? 'technical' : (prev.inquiryType || 'general')
      }));
    }
  }, [location]);

  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);

  const inquiryTypes = [
    { value: 'general', label: 'General Inquiry' },
    { value: 'feedback', label: 'Feedback & Suggestions' },
    { value: 'volunteer', label: 'Volunteer Application' },
    { value: 'technical', label: 'Technical Support' },
    { value: 'other', label: 'Other' }
  ];

  const validateForm = () => {
    const newErrors = {};

    if (!formData?.name?.trim()) {
      newErrors.name = 'Name is required';
    }

    if (!formData?.email?.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/?.test(formData?.email)) {
      newErrors.email = 'Please enter a valid email address';
    }

    if (!formData?.inquiryType) {
      newErrors.inquiryType = 'Please select an inquiry type';
    }

    if (!formData?.subject?.trim()) {
      newErrors.subject = 'Subject is required';
    }

    if (!formData?.message?.trim()) {
      newErrors.message = 'Message is required';
    } else if (formData?.message?.trim()?.length < 20) {
      newErrors.message = 'Message must be at least 20 characters';
    }

    if (!formData?.agreeToTerms) {
      newErrors.agreeToTerms = 'You must agree to the terms';
    }

    setErrors(newErrors);
    return Object.keys(newErrors)?.length === 0;
  };

  const handleSubmit = async (e) => {
    e?.preventDefault();

    // 1. Security Check: Honeypot Trap
    if (formData.bot_trap) {
      console.warn("Honeypot triggered. Bot detected.");
      // Silently fail or show a fake success to confuse the bot
      setSubmitSuccess(true);
      return;
    }

    if (validateForm()) {
      setIsSubmitting(true);
      try {
        await supabaseService.submitContactMessage({
          full_name: formData.name,
          email: formData.email,
          phone: formData.phone,
          subject: formData.subject,
          message: formData.message
        });

        setIsSubmitting(false);
        setSubmitSuccess(true);
        setFormData({
          name: '',
          email: '',
          phone: '',
          inquiryType: '',
          subject: '',
          message: '',
          agreeToTerms: false
        });

        setTimeout(() => {
          setSubmitSuccess(false);
        }, 5000);
      } catch (error) {
        console.error('Submission error:', error);
        setIsSubmitting(false);
        addToast('Failed to send message. Please try again later.', 'error');
      }
    }
  };

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    if (errors?.[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }));
    }
  };

  return (
    <section className="py-24 bg-slate-900 relative overflow-hidden">
      {/* Background Decor */}
      <div className="absolute top-1/4 left-0 w-64 h-64 bg-primary/5 blur-[100px] rounded-full" />
      <div className="absolute bottom-1/4 right-0 w-64 h-64 bg-secondary/5 blur-[100px] rounded-full" />

      <div className="max-w-4xl mx-auto px-4 md:px-6 lg:px-8 relative z-10">
        <div className="text-center mb-16">
          <h2 className="text-3xl md:text-5xl font-black text-white mb-6 italic tracking-tight">
            Send a <span className="text-secondary">Message</span>
          </h2>
          <p className="text-lg text-slate-400 max-w-2xl mx-auto font-medium leading-relaxed">
            Have a specific proposal or need support? Our global team is ready to assist you within 24 hours.
          </p>
        </div>

        {submitSuccess && (
          <div className="mb-12 p-8 bg-emerald-500/10 border border-emerald-500/20 rounded-[2rem] backdrop-blur-xl flex items-start gap-6 animate-in fade-in zoom-in duration-500">
            <div className="w-12 h-12 rounded-2xl bg-emerald-500/20 flex items-center justify-center shrink-0">
              <Icon name="CheckCircle" size={24} className="text-emerald-500" />
            </div>
            <div>
              <h4 className="font-black text-white mb-2 italic tracking-tight text-xl">Transmission Successful!</h4>
              <p className="text-slate-300 font-medium">
                Thank you for reaching out. We've received your message and our team will respond via email shortly.
              </p>
            </div>
          </div>
        )}

        <div className="bg-white/5 backdrop-blur-2xl rounded-[3rem] p-8 md:p-12 border border-white/10 shadow-2xl">
          <form onSubmit={handleSubmit} className="space-y-8 md:space-y-10">
            {/* Honeypot Trap - Hidden from humans, visible to bots */}
            <div className="hidden pointer-events-none opacity-0 absolute -z-10 h-0 overflow-hidden" aria-hidden="true">
              <label htmlFor="bot_trap">Do not fill this field if you are human</label>
              <input
                type="text"
                id="bot_trap"
                name="bot_trap"
                value={formData.bot_trap}
                onChange={(e) => handleChange('bot_trap', e.target.value)}
                tabIndex="-1"
                autoComplete="off"
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <Input
                label="Full Name"
                type="text"
                placeholder="Enter your full name"
                required
                value={formData?.name}
                onChange={(e) => handleChange('name', e?.target?.value)}
                error={errors?.name}
                className="bg-white/5 border-white/10 text-white placeholder:text-slate-500"
              />

              <Input
                label="Email Address"
                type="email"
                placeholder="your.email@example.com"
                required
                value={formData?.email}
                onChange={(e) => handleChange('email', e?.target?.value)}
                error={errors?.email}
                className="bg-white/5 border-white/10 text-white placeholder:text-slate-500"
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <Input
                label="Phone Number"
                type="tel"
                placeholder="+1 (555) 123-4567"
                value={formData?.phone}
                onChange={(e) => handleChange('phone', e?.target?.value)}
                description="Optional - for urgent matters"
                className="bg-white/5 border-white/10 text-white placeholder:text-slate-500"
              />

              <Select
                label="Inquiry Type"
                placeholder="Select inquiry type"
                required
                options={inquiryTypes}
                value={formData?.inquiryType}
                onChange={(value) => handleChange('inquiryType', value)}
                error={errors?.inquiryType}
                className="bg-white/5 border-white/10 text-white"
              />
            </div>

            <Input
              label="Subject"
              type="text"
              placeholder="Brief subject of your inquiry"
              required
              value={formData?.subject}
              onChange={(e) => handleChange('subject', e?.target?.value)}
              error={errors?.subject}
              className="bg-white/5 border-white/10 text-white placeholder:text-slate-500"
            />

            <div>
              <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-3">
                Message <span className="text-secondary">*</span>
              </label>
              <textarea
                rows={6}
                placeholder="Tell us more about your inquiry, feedback, or how you'd like to contribute..."
                value={formData?.message}
                onChange={(e) => handleChange('message', e?.target?.value)}
                className="w-full px-5 py-4 rounded-2xl border border-white/10 bg-white/5 text-white placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-secondary/50 transition-all duration-300 resize-none font-medium leading-relaxed"
              />
              {errors?.message && (
                <p className="mt-2 text-xs font-bold text-rose-400">{errors?.message}</p>
              )}
              <p className="mt-3 text-[10px] font-black uppercase tracking-widest text-slate-500">
                Minimum 20 characters required
              </p>
            </div>

            <div className="flex items-start gap-3">
              <Checkbox
                checked={formData?.agreeToTerms}
                onChange={(e) => handleChange('agreeToTerms', e?.target?.checked)}
                error={errors?.agreeToTerms}
                required
              />
              <span className="text-xs font-medium text-slate-400 mt-0.5">
                I agree to the terms and conditions and privacy policy
              </span>
            </div>

            <div className="flex flex-col sm:flex-row gap-6 pt-6">
              <Button
                type="submit"
                variant="default"
                size="xl"
                loading={isSubmitting}
                iconName="Send"
                iconPosition="right"
                className="bg-white text-slate-950 hover:bg-secondary hover:text-white font-black italic py-6 px-12 rounded-2xl shadow-2xl transition-all duration-300 w-full sm:w-auto"
              >
                {isSubmitting ? 'Transmitting...' : 'Send Message'}
              </Button>
              <Button
                type="button"
                variant="outline"
                size="xl"
                onClick={() => {
                  setFormData({
                    name: '',
                    email: '',
                    phone: '',
                    inquiryType: '',
                    subject: '',
                    message: '',
                    agreeToTerms: false
                  });
                  setErrors({});
                }}
                className="border-white/10 text-white hover:bg-white/5 font-black italic py-6 px-12 rounded-2xl w-full sm:w-auto"
              >
                Clear Form
              </Button>
            </div>
          </form>
        </div>

        <div className="mt-16 p-8 bg-white/5 backdrop-blur-2xl rounded-[2.5rem] border border-white/5">
          <div className="flex items-start gap-6">
            <div className="w-12 h-12 rounded-2xl bg-secondary/10 flex items-center justify-center shrink-0">
              <Icon name="Info" size={24} className="text-secondary" />
            </div>
            <div>
              <h4 className="font-black text-white mb-2 italic tracking-tight text-xl">Response Time Commitment</h4>
              <p className="text-slate-400 font-medium leading-relaxed">
                We typically respond to all inquiries within 24 hours during business days. For urgent matters, please join our global WhatsApp community for immediate assistance.
              </p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default ContactForm;