import React from 'react';
import Icon from '../../../components/AppIcon';

const LocationMap = ({ data }) => {
  const officeHours = data?.hours || [
    { day: "Monday - Friday", hours: "9:00 AM - 6:00 PM EST" }
  ];

  return (
    <section className="py-12 md:py-16 lg:py-20 bg-[var(--color-card)]">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-8 md:mb-12">
          <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold text-[var(--color-primary)] mb-4 md:mb-6" style={{ fontFamily: 'var(--font-headline)' }}>
            {data?.title || "Visit Our Community Hub"}
          </h2>
          <p className="text-base md:text-lg text-[var(--color-muted-foreground)] max-w-2xl mx-auto">
            {data?.description || "Drop by our physical location for in-person consultations."}
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 md:gap-8">
          <div className="lg:col-span-2 rounded-2xl overflow-hidden shadow-[var(--shadow-card)] border border-[var(--color-border)] h-[300px] md:h-[400px] lg:h-[500px]">
            <iframe
              width="100%"
              height="100%"
              loading="lazy"
              title="LUC Opportunities Office Location"
              referrerPolicy="no-referrer-when-downgrade"
              src={data?.mapUrl || "https://www.google.com/maps?q=40.7589,-73.9851&z=14&output=embed"}
              className="border-0"
            />
          </div>

          <div className="space-y-6">
            <div className="bg-[var(--color-background)] rounded-2xl p-6 md:p-8 shadow-[var(--shadow-card)] border border-[var(--color-border)]">
              <div className="flex items-start gap-4 mb-6">
                <div className="w-12 h-12 rounded-xl bg-[var(--color-brand-blue)]/10 flex items-center justify-center flex-shrink-0">
                  <Icon name="MapPin" size={24} color="var(--color-brand-blue)" />
                </div>
                <div className="flex-1 min-w-0">
                  <h3 className="text-lg md:text-xl font-semibold text-[var(--color-primary)] mb-2" style={{ fontFamily: 'var(--font-headline)' }}>
                    Office Address
                  </h3>
                  <p className="text-sm md:text-base text-[var(--color-muted-foreground)] whitespace-pre-line leading-relaxed">
                    {data?.address || "123 Opportunity Lane\nInnovation District\nNew York, NY 10001"}
                  </p>
                </div>
              </div>

              <div className="flex items-start gap-4">
                <div className="w-12 h-12 rounded-xl bg-[var(--color-success)]/10 flex items-center justify-center flex-shrink-0">
                  <Icon name="Clock" size={24} color="var(--color-success)" />
                </div>
                <div className="flex-1 min-w-0">
                  <h3 className="text-lg md:text-xl font-semibold text-[var(--color-primary)] mb-3" style={{ fontFamily: 'var(--font-headline)' }}>
                    Office Hours
                  </h3>
                  <div className="space-y-2">
                    {officeHours?.map((schedule, index) => (
                      <div key={index} className="flex justify-between items-center text-sm md:text-base">
                        <span className="text-[var(--color-muted-foreground)]">{schedule?.day}</span>
                        <span className="font-medium text-[var(--color-foreground)]">{schedule?.hours}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-[var(--color-background)] rounded-2xl p-6 md:p-8 shadow-[var(--shadow-card)] border border-[var(--color-border)]">
              <div className="flex items-start gap-4 mb-4">
                <div className="w-12 h-12 rounded-xl bg-[var(--color-accent)]/10 flex items-center justify-center flex-shrink-0">
                  <Icon name="Navigation" size={24} color="var(--color-accent)" />
                </div>
                <div className="flex-1 min-w-0">
                  <h3 className="text-lg md:text-xl font-semibold text-[var(--color-primary)] mb-2" style={{ fontFamily: 'var(--font-headline)' }}>
                    Getting Here
                  </h3>
                  <p className="text-sm md:text-base text-[var(--color-muted-foreground)] leading-relaxed mb-4">
                    {data?.gettingHere || "Easily accessible by subway and multiple bus routes."}
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="mt-8 md:mt-12 bg-gradient-to-r from-[var(--color-brand-blue)]/10 to-[var(--color-brand-purple)]/10 rounded-2xl p-6 md:p-8 border border-[var(--color-brand-blue)]/20">
          <div className="flex flex-col md:flex-row items-start md:items-center gap-4 md:gap-6">
            <div className="w-12 h-12 md:w-16 md:h-16 rounded-xl bg-white flex items-center justify-center flex-shrink-0">
              <Icon name="Calendar" size={24} color="var(--color-brand-blue)" className="md:w-8 md:h-8" />
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="text-lg md:text-xl font-semibold text-[var(--color-primary)] mb-2" style={{ fontFamily: 'var(--font-headline)' }}>
                {data?.scheduleVisit?.title || "Schedule a Visit"}
              </h3>
              <p className="text-sm md:text-base text-[var(--color-muted-foreground)] leading-relaxed">
                {data?.scheduleVisit?.description || "Planning to visit? Book an appointment."}
              </p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default LocationMap;